ALTER TABLE public.simulation_wallets ALTER COLUMN balance SET DEFAULT 10000;
ALTER TABLE public.simulation_wallets ALTER COLUMN discoverable SET DEFAULT true;
ALTER TABLE public.simulation_wallets ADD COLUMN email text NOT NULL DEFAULT '';
CREATE OR REPLACE FUNCTION public.create_simulation_wallet() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE ph text:=regexp_replace(NEW.phone,'[^0-9]','','g'); up text:=lower(trim(NEW.upi_id)); em text;
BEGIN
SELECT lower(trim(email)) INTO em FROM auth.users WHERE id=NEW.id;
IF ph !~ '^[0-9]{10,15}$' OR EXISTS(SELECT 1 FROM public.simulation_wallets WHERE phone=ph) THEN ph:=''; END IF;
IF up !~ '^[a-z0-9._-]+@[a-z0-9.-]+$' OR EXISTS(SELECT 1 FROM public.simulation_wallets WHERE upi_id=up) THEN up:=''; END IF;
INSERT INTO public.simulation_wallets(user_id,balance,phone,upi_id,email,discoverable) VALUES(NEW.id,10000,ph,up,coalesce(em,''),true) ON CONFLICT(user_id) DO NOTHING;
RETURN NEW; END $$;
INSERT INTO public.simulation_wallets(user_id) SELECT id FROM public.profiles ON CONFLICT(user_id) DO NOTHING;
UPDATE public.simulation_wallets w SET balance=10000, discoverable=true, email=coalesce((SELECT lower(trim(email)) FROM auth.users WHERE id=w.user_id),'');
WITH candidates AS (SELECT p.id,regexp_replace(p.phone,'[^0-9]','','g') ph FROM public.profiles p)
UPDATE public.simulation_wallets w SET phone=c.ph FROM candidates c WHERE w.user_id=c.id AND w.phone='' AND c.ph ~ '^[0-9]{10,15}$' AND (SELECT count(*) FROM candidates d WHERE d.ph=c.ph)=1 AND NOT EXISTS(SELECT 1 FROM public.simulation_wallets d WHERE d.phone=c.ph);
WITH candidates AS (SELECT p.id,lower(trim(p.upi_id)) up FROM public.profiles p)
UPDATE public.simulation_wallets w SET upi_id=c.up FROM candidates c WHERE w.user_id=c.id AND w.upi_id='' AND c.up ~ '^[a-z0-9._-]+@[a-z0-9.-]+$' AND (SELECT count(*) FROM candidates d WHERE d.up=c.up)=1 AND NOT EXISTS(SELECT 1 FROM public.simulation_wallets d WHERE d.upi_id=c.up);
CREATE OR REPLACE FUNCTION public.ensure_simulation_wallet() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
INSERT INTO public.simulation_wallets(user_id,email) SELECT p.id,coalesce(lower(trim(u.email)),'') FROM public.profiles p JOIN auth.users u ON u.id=p.id WHERE p.id=auth.uid() ON CONFLICT(user_id) DO UPDATE SET email=excluded.email;
IF NOT EXISTS(SELECT 1 FROM public.simulation_wallets WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Your account profile is missing'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.ensure_simulation_wallet() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.ensure_simulation_wallet() TO authenticated;
ALTER TABLE public.simulation_transfers DROP CONSTRAINT simulation_transfers_status_check;
ALTER TABLE public.simulation_transfers ADD CONSTRAINT simulation_transfers_status_check CHECK(status IN ('AWAITING_USER_AUTH','SUCCESS','FAILED','CANCELLED'));
DROP INDEX public.simulation_sync_once;
CREATE UNIQUE INDEX simulation_sync_once ON public.simulation_transfers(sync_request_id) WHERE sync_request_id IS NOT NULL AND status IN ('AWAITING_USER_AUTH','SUCCESS');
CREATE OR REPLACE FUNCTION payiq_private.configure_simulation_wallet(p_phone text,p_upi text,p_discoverable boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; PERFORM public.ensure_simulation_wallet(); IF p_phone<>'' AND p_phone !~ '^[0-9]{10,15}$' THEN RAISE EXCEPTION 'Use 10 to 15 digits'; END IF; IF p_upi<>'' AND p_upi !~ '^[a-z0-9._-]+@[a-z0-9.-]+$' THEN RAISE EXCEPTION 'Invalid simulation UPI alias'; END IF; UPDATE public.simulation_wallets SET phone=p_phone,upi_id=p_upi,discoverable=p_discoverable WHERE user_id=auth.uid(); END $$;
CREATE OR REPLACE FUNCTION payiq_private.top_up_simulation_wallet(p_amount numeric) RETURNS numeric LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b numeric; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; PERFORM public.ensure_simulation_wallet(); IF p_amount IS NULL OR p_amount<=0 OR p_amount>100000 OR p_amount<>round(p_amount,2) THEN RAISE EXCEPTION 'Enter 0.01 to 100000 fake rupees with at most two decimals'; END IF; UPDATE public.simulation_wallets SET balance=balance+p_amount WHERE user_id=auth.uid() AND balance+p_amount<=1000000 RETURNING balance INTO b; IF b IS NULL THEN RAISE EXCEPTION 'Fake balance limit is 1000000'; END IF; INSERT INTO public.transactions(user_id,order_id,bank_ref,from_party,to_party,direction,source_type,amount,status,is_simulated) VALUES(auth.uid(),'SIM-TOPUP-'||gen_random_uuid(),'SIMULATION','Simulation top-up','Your wallet','CREDIT','DIRECT_PAYMENT',p_amount,'SUCCESS',true); RETURN b; END $$;
CREATE OR REPLACE FUNCTION payiq_private.search_simulation_recipient(p_query text) RETURNS TABLE(user_id uuid,name text,alias text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; PERFORM public.ensure_simulation_wallet(); RETURN QUERY SELECT w.user_id,p.name,CASE WHEN w.email=lower(trim(p_query)) THEN w.email WHEN w.upi_id=lower(trim(p_query)) THEN w.upi_id ELSE w.phone END FROM public.simulation_wallets w JOIN public.profiles p ON p.id=w.user_id WHERE w.discoverable AND w.user_id<>auth.uid() AND (w.email=lower(trim(p_query)) AND w.email<>'' OR w.phone=trim(p_query) AND w.phone<>'' OR w.upi_id=lower(trim(p_query)) AND w.upi_id<>'') LIMIT 2; END $$;
CREATE OR REPLACE FUNCTION payiq_private.prepare_simulation_transfer(p_recipient uuid,p_amount numeric,p_sync uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.sync_requests; payer uuid:=auth.uid(); receiver uuid:=p_recipient; result uuid; BEGIN IF payer IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; PERFORM public.ensure_simulation_wallet(); IF p_amount IS NULL OR p_amount<=0 OR p_amount>100000 OR p_amount<>round(p_amount,2) THEN RAISE EXCEPTION 'Invalid fake amount'; END IF; IF NOT EXISTS(SELECT 1 FROM public.simulation_wallets WHERE user_id=p_recipient AND discoverable) THEN RAISE EXCEPTION 'Recipient unavailable'; END IF; IF p_recipient=payer THEN RAISE EXCEPTION 'Cannot pay yourself'; END IF; IF p_sync IS NOT NULL THEN SELECT * INTO s FROM public.sync_requests WHERE id=p_sync AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Request not found'; END IF; IF s.amount_type='FIXED' AND s.amount<>p_amount THEN RAISE EXCEPTION 'Amount must match fixed request'; END IF; IF s.max_cap IS NOT NULL AND p_amount>s.max_cap THEN RAISE EXCEPTION 'Amount exceeds cap'; END IF; IF NOT EXISTS(SELECT 1 FROM public.simulation_wallets WHERE user_id=p_recipient AND (phone=trim(s.counterparty_address) OR upi_id=lower(trim(s.counterparty_address)) OR email=lower(trim(s.counterparty_address)) OR (s.counterparty_email<>'' AND email=lower(trim(s.counterparty_email))))) THEN RAISE EXCEPTION 'Recipient must match request'; END IF; IF s.direction='CREDIT' THEN payer:=p_recipient; receiver:=auth.uid(); END IF; END IF; INSERT INTO public.simulation_transfers(requester_id,payer_id,recipient_id,amount,sync_request_id) VALUES(auth.uid(),payer,receiver,p_amount,p_sync) RETURNING id INTO result; RETURN result; END $$;
CREATE OR REPLACE FUNCTION payiq_private.confirm_simulation_transfer(p_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.simulation_transfers; pn text; rn text; tx uuid; rx uuid; failure text; BEGIN SELECT * INTO t FROM public.simulation_transfers WHERE id=p_id AND payer_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Only payer can confirm'; END IF; IF t.status IN ('SUCCESS','FAILED') THEN RETURN t.id; END IF; IF t.status<>'AWAITING_USER_AUTH' THEN RAISE EXCEPTION 'Request is no longer pending'; END IF; PERFORM 1 FROM public.simulation_wallets WHERE user_id IN(t.payer_id,t.recipient_id) ORDER BY user_id FOR UPDATE; IF (SELECT count(*) FROM public.simulation_wallets WHERE user_id IN(t.payer_id,t.recipient_id))<>2 THEN RAISE EXCEPTION 'A simulation wallet is missing'; END IF; IF (SELECT balance FROM public.simulation_wallets WHERE user_id=t.payer_id)<t.amount THEN failure:='Insufficient fake balance'; ELSIF (SELECT balance FROM public.simulation_wallets WHERE user_id=t.recipient_id)+t.amount>1000000 THEN failure:='Recipient fake balance limit is 1000000'; END IF; IF failure IS NULL THEN UPDATE public.simulation_wallets SET balance=balance-t.amount WHERE user_id=t.payer_id; UPDATE public.simulation_wallets SET balance=balance+t.amount WHERE user_id=t.recipient_id; END IF; SELECT name INTO pn FROM public.profiles WHERE id=t.payer_id; SELECT name INTO rn FROM public.profiles WHERE id=t.recipient_id; INSERT INTO public.transactions(user_id,order_id,bank_ref,from_party,to_party,direction,source_type,amount,status,is_simulated,sync_request_id) VALUES(t.payer_id,'SIM-'||t.id||'-D','SIMULATION',pn,rn,'DEBIT',CASE WHEN t.sync_request_id IS NULL THEN 'DIRECT_PAYMENT' ELSE 'SYNC_REQUEST' END,t.amount,CASE WHEN failure IS NULL THEN 'SUCCESS' ELSE 'FAILED' END,true,CASE WHEN t.requester_id=t.payer_id THEN t.sync_request_id ELSE NULL END) RETURNING id INTO tx; INSERT INTO public.transactions(user_id,order_id,bank_ref,from_party,to_party,direction,source_type,amount,status,is_simulated,sync_request_id) VALUES(t.recipient_id,'SIM-'||t.id||'-C','SIMULATION',pn,rn,'CREDIT',CASE WHEN t.sync_request_id IS NULL THEN 'DIRECT_PAYMENT' ELSE 'SYNC_REQUEST' END,t.amount,CASE WHEN failure IS NULL THEN 'SUCCESS' ELSE 'FAILED' END,true,CASE WHEN t.requester_id=t.recipient_id THEN t.sync_request_id ELSE NULL END) RETURNING id INTO rx; UPDATE public.transactions SET bank_error=failure WHERE id IN(tx,rx); INSERT INTO public.transaction_events(user_id,transaction_id,event) VALUES(t.payer_id,tx,coalesce(failure,'Simulated transfer confirmed; no real money moved')),(t.recipient_id,rx,coalesce(failure,'Simulated transfer received; no real money moved')); UPDATE public.simulation_transfers SET status=CASE WHEN failure IS NULL THEN 'SUCCESS' ELSE 'FAILED' END WHERE id=t.id; IF t.sync_request_id IS NOT NULL THEN UPDATE public.sync_requests SET last_at=now(), approved_at=CASE WHEN failure IS NULL THEN now() ELSE approved_at END, status=CASE WHEN failure IS NULL THEN 'ACTIVE' ELSE 'FAILED' END WHERE id=t.sync_request_id; END IF; RETURN t.id; END $$;